// Mechanical build of kit 2939. The deck is fitted to the frame with the kit's two posts.
// Each installed motor has its routed, unplugged leads. The driver and battery are optional equipment.
Robot adafruit_mini_rover {
    intent "Inspect the assembled Adafruit 2939 differential-drive chassis kit"
    Diff_two_caster chassis(ref = "adafruit_2939_frame_with_deck")
    Motor left_motor(ref = "adafruit_2939_fm90_left", glue = (-0.0555, 0.0355, -0.0141, 0, 1, 0))
    Motor right_motor(ref = "adafruit_2939_fm90_right", glue = (-0.0555, -0.0355, -0.0141, 0, -1, 0))
    Standard left_wheel(ref = "adafruit_2939_wheel", glue = (-0.0498, 0.044, -0.0141, 0, 1, 0))
    Standard right_wheel(ref = "adafruit_2939_wheel", glue = (-0.0498, -0.044, -0.0141, 0, -1, 0))
    Caster front_caster(ref = "adafruit_2939_swivel_caster", glue = (0.020142857, 0, -0.0015, 0, 0, -1))
}

