// A Hiwonder JetRover as its Standard Kit builds it on the mecanum chassis: the body on four mecanum wheels,
// with the kit's LiDAR under the upper deck and its six-axis arm on the turntable, holding the depth camera at
// its wrist. The arm is in the pose the maker's software starts it in for mapping, where the camera looks
// straight ahead. The kit is sold without a computer.
// The camera uses the factory M3 x 6 screws and the measured rear-hole pair; its pose follows the bracket face.
Robot jetrover {
    intent "Hiwonder JetRover mecanum base with its LiDAR, its arm and the depth camera on the arm"

    Mecanum_four_wheel chassis(ref = "hiwonder_jetrover_chassis")

    // The kit's motors, each on its bracket at a wheel.
    // Installed battery -> factory controller -> independent drive circuits.
    Motor motor_front_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (0.097415569, 0.070505, -0.067844107, 0, 1, 0), command = @core/chassis)
    Motor motor_front_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (0.097415569, -0.070495, -0.067844107, 0, -1, 0), command = @core/chassis)
    Motor motor_rear_left(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.097513077, 0.070825305, -0.067844107, 0, 1, 0), command = @core/chassis)
    Motor motor_rear_right(ref = "hiwonder_520_gearmotor_90_12v", glue = (-0.097513077, -0.070825313, -0.067844107, 0, -1, 0), command = @core/chassis)

    Mecanum wheel_front_left(ref = "hiwonder_mecanum_wheel_97mm_fl_rr", glue = (0.0975, 0.1095, -0.0678, 0, 1, 0))
    Mecanum wheel_front_right(ref = "hiwonder_mecanum_wheel_97mm_fr_rl", glue = (0.0975, -0.1095, -0.0678, 0, -1, 0))
    Mecanum wheel_rear_left(ref = "hiwonder_mecanum_wheel_97mm_fr_rl", glue = (-0.0975, 0.1095, -0.0678, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "hiwonder_mecanum_wheel_97mm_fl_rr", glue = (-0.0975, -0.1095, -0.0678, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_jetrover_lidar", glue = (0.09, 0, 0.002, 0, 0, 1))
    Attachment arm(ref = "hiwonder_jetrover_arm", glue = (0.0251, 0, 0.0774, 0, 0, 1), power = @core/chassis, output = "servo_bus")
    RGBD camera(ref = "hiwonder_jetrover_depth_camera", on = @core/arm, at = "camera_bracket_holes", by = "rear_camera_threads")
}

