// A Hiwonder LanderPi as its Standard Kit builds it on the mecanum chassis: the body on four mecanum wheels,
// with the kit's LiDAR at the front of the middle deck and its six-axis arm on the turntable, holding the depth
// camera at its wrist. The arm is in the pose the maker's LiDAR app puts it in to drive, where the camera looks
// ahead and down. The kit is sold without a Raspberry Pi 5; this example does not include that board.
Robot landerpi {
    intent "Hiwonder LanderPi mecanum base with its LiDAR, its arm and the depth camera on the arm"

    Mecanum_four_wheel chassis(ref = "hiwonder_landerpi_chassis")

    Mecanum wheel_front_left(ref = "hiwonder_landerpi_mecanum_wheel_fl_rr", glue = (0.0668, 0.0716, -0.0211, 0, 1, 0))
    Mecanum wheel_front_right(ref = "hiwonder_landerpi_mecanum_wheel_fr_rl", glue = (0.0668, -0.0716, -0.0211, 0, -1, 0))
    Mecanum wheel_rear_left(ref = "hiwonder_landerpi_mecanum_wheel_fr_rl", glue = (-0.0677, 0.0716, -0.0211, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "hiwonder_landerpi_mecanum_wheel_fl_rr", glue = (-0.0677, -0.0716, -0.0211, 0, -1, 0))

    Lidar lidar(ref = "hiwonder_landerpi_lidar", glue = (0.073, 0, 0.018, 0, 0, 1))
    // The native controller supplies the documented three-pin arm bus; its voltage/current are unpublished.
    Attachment arm(ref = "hiwonder_landerpi_arm", glue = (0.0446, 0, 0.0691, 0, 0, 1), power = @core/chassis, output = "arm_bus", data = @core/chassis, port = "arm_uart")
    RGBD camera(ref = "hiwonder_landerpi_depth_camera", on = @core/arm, at = "kit_camera_plate", by = "kit_rear_threads")
}

