// LEGO Technic 42099, the 4x4 X-treme Off-Roader, as its instructions build it: the body with its Control+ hub,
// the L motor that steers the front wheels through a rack, and the two XL motors that drive the front and the rear
// axle, each through a differential and the planetary hubs; the car drives all four wheels.
Robot lego_42099 {
    intent "LEGO Technic 42099 4x4 X-treme Off-Roader, an Ackermann base driving all four wheels"

    Ackermann chassis(ref = "lego_42099_chassis")

    // The modeled chassis includes its installed battery and motor controller.
    // LEGO instructions 6314520.pdf, pp. 48, 56, 64, 102-108, 132-134: front XL -> A, rear XL -> B.
    // C is occupied by the retained L steering motor; D is unused. C is not spare drive capacity.
    Motor motor_front(ref = "lego_controlplus_xl_motor", glue = (0.0409, 0, 0.0418, -0.9998, 0, 0.02), command = @core/chassis, channel = "A")
    Motor motor_rear(ref = "lego_controlplus_xl_motor", glue = (-0.0871, 0, 0.0445, 0.9998, 0, -0.02), command = @core/chassis, channel = "B")

    Standard wheel_front_left(ref = "lego_42099_wheel", glue = (0.112, 0.09112, 0, 0, 1, 0))
    Standard wheel_front_right(ref = "lego_42099_wheel", glue = (0.112, -0.09112, 0, 0, -1, 0))
    Standard wheel_rear_left(ref = "lego_42099_wheel", glue = (-0.112, 0.08925, 0, 0, 1, 0))
    Standard wheel_rear_right(ref = "lego_42099_wheel", glue = (-0.112, -0.08925, 0, 0, -1, 0))
}

