    Motor motor_left(ref = "lego_nxt_motor", glue = (0, 0.0315, 0, -0.04, 0, -0.9992), command = @core/chassis)
    Motor motor_right(ref = "lego_nxt_motor", glue = (0, -0.0325, 0, -0.04, 0, -0.9992), command = @core/chassis)

