// The Tri-bot of LEGO Mindstorms NXT 8527 with its touch sensor attachment and its ultrasonic sensor, as the LDraw
// Official Model Repository's 8527-1_Tri-bot builds them: the NXT brick on two NXT motors, each driving one wheel, a
// rear support of two belt wheels, and at the front the touch sensor behind the paddle that swings onto its button,
// the ultrasonic sensor on top of it, looking forward. The claws are left out.
Robot lego_8527_tribot_sensors {
    intent "LEGO Mindstorms NXT Tri-bot with its touch and ultrasonic sensors, a two-wheel differential base that sees what is ahead and feels what it runs into"

    Diff_two_caster chassis(ref = "lego_8527_tribot_chassis")

    // The modeled chassis includes its installed battery and motor controller.
    // Each unnamed command uses a distinct drive circuit; printed socket assignment is unverified.
    Motor motor_left(ref = "lego_nxt_motor", glue = (0, 0.0315, 0, -0.04, 0, -0.9992), command = @core/chassis)
    Motor motor_right(ref = "lego_nxt_motor", glue = (0, -0.0325, 0, -0.04, 0, -0.9992), command = @core/chassis)

    Standard wheel_left(ref = "lego_8527_tribot_wheel", glue = (0, 0.056, 0, 0, 1, 0))
    Standard wheel_right(ref = "lego_8527_tribot_wheel", glue = (0, -0.056, 0, 0, -1, 0))

    Bumper touch(ref = "lego_8527_touch_sensor", glue = (0.037008, -0.000515, 0.023531, 1, 0, 0))
    // NXT sonar needs separate pin-1 and pin-4 supplies; a single rail would be incorrect.
    Ultrasonic sonar(ref = "lego_8527_ultrasonic_sensor", glue = (0.086175, -0.000515, 0.061965, 1, 0, 0))
}

