files.core:
// A Yahboom Raspbot V2 as its Standard kit builds it: the body on four mecanum wheels, with the kit's ultrasonic
// module looking out of the front box and its camera on the gimbal above it. The kit is sold with or without a
// computer; this one is without, and a Raspberry Pi 5, bought beside it, lies under the cover.
Robot raspbot_v2 {
    intent "Yahboom Raspbot V2 mecanum base with its ultrasonic module, its camera and a Raspberry Pi 5"

    // The installed YB-MPF01 board takes the supplied pack at its T connector.
    Mecanum_four_wheel chassis(ref = "yahboom_raspbot_v2_chassis", power = @core/battery)

    Battery battery(ref = "yahboom_7_4v_2000mah_battery", glue = (-0.000002170386, -0.000003986155, -0.029002965816, 0, 0, 1))

    // A mecanum wheel has a hand: the same one goes front-left and rear-right, the other front-right and rear-left.
    Mecanum wheel_front_left(ref = "yahboom_raspbot_v2_mecanum_wheel_fl_rr", glue = (0.0586, 0.0663, -0.0148, 0, 1, 0))
    Mecanum wheel_front_right(ref = "yahboom_raspbot_v2_mecanum_wheel_fr_rl", glue = (0.0586, -0.0663, -0.0148, 0, -1, 0))
    Mecanum wheel_rear_left(ref = "yahboom_raspbot_v2_mecanum_wheel_fr_rl", glue = (-0.0586, 0.0663, -0.0148, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "yahboom_raspbot_v2_mecanum_wheel_fl_rr", glue = (-0.0586, -0.0663, -0.0148, 0, -1, 0))

    // The kit's four-wire ultrasonic cable uses the board's documented 5 V header.
    // This connection does not establish the module's accepted voltage range.
    Ultrasonic sonar(ref = "yahboom_raspbot_v2_ultrasonic", power = @core/chassis, output = "sonar_power", glue = (0.0779, 0, 0.016, 1, 0, 0))
    // The kit camera sends video over USB to the Pi; its separate gimbal servo wiring remains unresolved.
    // Yahboom Raspbot-V2, 16.Raspberry Pi basic settings/9. Use USB Camera.pdf.
    Camera camera(ref = "yahboom_raspbot_v2_camera", glue = (0.06, 0, 0.03, 0, 0, 1), data = @core/computer, port = "usb2_0")
    // Original M2.5 spacer stack; Raspbot V2 manual, page 14, steps 4 and 6.
    // Power-only Type-C cable from the board: 5.1 V / 5 A, with the Pi 5 protocol.
    Attachment computer(ref = "raspberry_pi_5_8gb", power = @core/chassis, output = "pi_power", on = @core/chassis, at = "computer_studs", by = "mounting_holes")
}

