// A Yahboom ROSMASTER A1 as its Ultimate kit builds it: the body on four rubber wheels, the front pair steered and the
// rear pair driven, with the kit's LiDAR on the roof and its depth camera on the nose. The kit is sold without a
// computer; a Raspberry Pi 5, bought beside it, lies under the roof on the kit's USB hub board.
Robot rosmaster_a1 {
    intent "Yahboom ROSMASTER A1 Ackermann base with its LiDAR, its depth camera and a Raspberry Pi 5"

    Ackermann chassis(ref = "yahboom_rosmaster_a1_chassis")

    Standard wheel_front_left(ref = "yahboom_rosmaster_a1_wheel", glue = (0.097, 0.08735, 0.0146, 0, 1, 0))
    Standard wheel_front_right(ref = "yahboom_rosmaster_a1_wheel", glue = (0.097, -0.08735, 0.0146, 0, -1, 0))
    Standard wheel_rear_left(ref = "yahboom_rosmaster_a1_wheel", glue = (-0.097, 0.08735, 0.0145, 0, 1, 0))
    Standard wheel_rear_right(ref = "yahboom_rosmaster_a1_wheel", glue = (-0.097, -0.08735, 0.0145, 0, -1, 0))

    Lidar lidar(ref = "yahboom_rosmaster_a1_lidar", glue = (0.00606, 0, 0.122, 0, 0, 1))
    // The native pack feeds its V3.0 controller; Type-C 5.1 V / 5 A powers the Pi.
    // The depth camera uses one USB cable for data and power from that Pi.
    RGBD camera(ref = "yahboom_rosmaster_a1_depth_camera", glue = (0.0915, 0, 0.0825, 0, 0, 1), power = @core/computer, output = "usb_power", data = @core/computer, port = "usb2_0")
    Attachment computer(ref = "raspberry_pi_5_8gb", glue = (-0.031, -0.016, 0.0787, 0, 0, 1), power = @core/chassis, output = "pi_power")
}

