    Mecanum wheel_rear_left(ref = "yahboom_rosmaster_m3_mecanum_wheel_fr_rl", glue = (-0.0795, 0.08715, -0.0996, 0, 1, 0))
    Mecanum wheel_rear_right(ref = "yahboom_rosmaster_m3_mecanum_wheel_fl_rr", glue = (-0.0795, -0.08715, -0.0996, 0, -1, 0))

    // The kit tutorial connects this LiDAR to the controller's left UART4 socket.
    // Its physical supply is declared, while that header's voltage/current remain unknown.
    Lidar lidar(ref = "yahboom_rosmaster_m3_lidar", glue = (0.0351, 0, 0, 0, 0, 1), data = @core/chassis, port = "lidar_uart4", power = @core/chassis, output = "lidar_power")
    // The included pack feeds the native control board; its Type-C 5.1 V / 5 A output powers the Pi.
    // The depth camera uses one USB cable for data and power from that Pi.
    RGBD camera(ref = "yahboom_rosmaster_m3_depth_camera", glue = (0.0855, 0, -0.0448, 0, 0, 1), power = @core/computer, output = "usb_power", data = @core/computer, port = "usb2_0")
    Attachment computer(ref = "raspberry_pi_5_8gb", glue = (-0.017, -0.016, -0.0414, 0, 0, 1), power = @core/chassis, output = "pi_power")
}

